function _asideApplyState(){const toggle=document.getElementById('staff-aside-toggle');const content=document.getElementById('staff-aside-content');if(!toggle||!content)return;let open=false;try{open=localStorage.getItem('staff-aside-open')==='true'}catch(e){}content.hidden=!open;toggle.setAttribute('aria-expanded',open?'true':'false')}document.addEventListener('DOMContentLoaded',function(){_asideApplyState();document.body.addEventListener('click',function(e){const toggle=e.target.closest('#staff-aside-toggle');if(!toggle)return;const content=document.getElementById('staff-aside-content');if(!content)return;const open=content.hidden;content.hidden=!open;toggle.setAttribute('aria-expanded',open?'true':'false');try{localStorage.setItem('staff-aside-open',open?'true':'false')}catch(e){}})});
